mapper.select:
SELECT	${query1}
DEVICE_SEQ as deviceSeq, DEVICE_NM as deviceNm
FROM	(
SELECT	${query2}
A.DEVICE_SEQ, A.DEVICE_NM
FROM	UI_DEVICE A, UI_DEVICE_TRAFFIC_STAT B
WHERE	A.DEVICE_SEQ = B.DEVICE_SEQ
AND		DATE_FORMAT(B.INSERT_DT,'%Y%m%d') BETWEEN	#{startDt}	AND	#{endDt}
AND		A.DEVICE_TYPE = 'A'
GROUP	BY A.DEVICE_SEQ, A.DEVICE_NM
ORDER	BY A.CREATE_DT DESC
) RS

mapper.update:
REPLACE	INTO UI_DEVICE_TRAFFIC_STAT ( DEVICE_SEQ, INSERT_DT, PORT, DIRECTION, HOUR_SIZE, HOUR_CNT, UPDATE_DT )
SELECT	#{deviceSeq}, IFNULL(MIN(INSERT_DT),NOW()), #{port}, #{direction}, IFNULL(MAX(HOUR_SIZE),0) + #{hourSize}, IFNULL(MAX(HOUR_CNT),0) + #{hourCnt}, NOW()
FROM	UI_DEVICE_TRAFFIC_STAT
WHERE	DEVICE_SEQ = #{deviceSeq}
AND		DATE_FORMAT(UPDATE_DT, '%Y-%m-%d %H') = #{updateDt}
AND		PORT = #{port}
AND		DIRECTION = #{direction}
